(async()=>{const w=ms=>new Promise(r=>setTimeout(r,ms));const bad=[];
const chk=name=>{const sc=document.querySelector('.screen.active');if(!sc)return;
 sc.querySelectorAll('button,input,.btn,h1,h2,h3,.snack,.opt,.acc-row,.date,.time,.seat').forEach(e=>{if(!e.offsetParent)return;const r=e.getBoundingClientRect();if(!r.width||!r.height)return;
  if(e.closest('.now,.snban,#fan,.tabs,.cast,.sntabs,.muv,.muv-panel,.sheet,#toast,.sv,.fchips,.qchips,.seg,.hslots,.d-chips'))return;
  if(r.right>innerWidth+1||r.left<-1)bad.push(name+': '+(e.id||e.className||e.tagName).toString().slice(0,26)+' '+Math.round(r.left)+'-'+Math.round(r.right))});
 if(document.documentElement.scrollWidth>innerWidth+1)bad.push(name+': page plus large '+document.documentElement.scrollWidth)};
document.querySelector('#onbSkip').click();await w(1300);ST.seats=['E4','E5'];ST.count=2;
for(const n of ['home','detail','book','seats','order','account']){go(n);await w(1000);if(n==='order'){document.querySelector('#snTog').click();await w(500)}chk(n)}
return innerWidth+'x'+innerHeight+' : '+(bad.length?bad.slice(0,6).join(' | '):'aucun défaut')})()
